def radar():
 import math
 cx,cy,r=145,117,82
 xy=lambda rr:[(cx+math.sin(i*math.tau/5)*rr,cy-math.cos(i*math.tau/5)*rr) for i in range(5)]
 pts=lambda q:' '.join(f'{x:.1f},{y:.1f}' for x,y in q)
 ss=['<svg class="radar" viewBox="0 0 290 240" role="img" aria-label="五维表现示意雷达图">']
 for f in [.25,.5,.75,1]:ss.append(f'<polygon class="grid" points="{pts(xy(r*f))}"/>')
 for x,y in xy(r):ss.append(f'<line class="guide" x1="{cx}" y1="{cy}" x2="{x}" y2="{y}"/>')
 labels=['竞技积累','表现质量','出场稳定','成长趋势','荣誉成就']
 for (x,y),lab in zip(xy(r+24),labels):ss.append(f'<text x="{x}" y="{y+4}" text-anchor="middle" class="axis-text">{lab}</text>')
 vals=[.9,.79,.86,.72,.68]; q=[(cx+(x-cx)*v,cy+(y-cy)*v) for (x,y),v in zip(xy(r),vals)]
 ss.append(f'<polygon class="shape" points="{pts(q)}"/>')
 for x,y in q:ss.append(f'<circle class="vertex" cx="{x}" cy="{y}" r="3.5"/>')
 ss.append('</svg>');return ''.join(ss)
